    if (nums.length == 1) {
        result.add(Arrays.asList(nums));
        return result;
    }
    for (int i = 0; i < nums.length; i++) {
        int[] numsCopy = nums.clone();
        int tmp = numsCopy[i];
        numsCopy[i] = numsCopy[0];
        numsCopy[0] = tmp;
        List<List<Integer>> permutations = permute(numsCopy);
        result.addAll(permutations);
