public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> permutations = new ArrayList<>();

    // Base case: If the input array has only one element,
    // return a list with only that element
    if (nums.length == 1) {
        List<Integer> permutation = new ArrayList<>();
        permutation.add(nums[0]);
        permutations.add(permutation);
        return permutations;
    }

    // Recursive case: For each element in the input array,
    // recursively permute the remaining elements
    for (int i = 0; i < nums.length; i++) {
        int num = nums[i];
        List<List<Integer>> subPermutations = permute(Arrays.copyOfRange(nums, 0, i)
            .concat(Arrays.copyOfRange(nums, i + 1, nums.length)));
        for (List<Integer> subPermutation : subPermutations) {
            subPermutation.add(0, num);
            permutations.add(subPermutation);
        }
    }

    return permutations;
}

